using System;using LestingCraft.World;using LestingCraft.Gameplay;
class CheckExpedition
{
 static void Main(string[] args){int checks=0;foreach(var r in CraftingTable.All){var inv=new Inventory();foreach(var id in r.Pattern)if(id>0){if(!Items.Exists(id)||!inv.Add(id,1))throw new Exception("recipe input "+id);}if(!Items.Exists(r.Output)||!CraftingTable.Fill(inv,r,3))throw new Exception("recipe fill "+r.Output);var matched=CraftingTable.Match(inv.grid,3);if(matched==null||matched.Output!=r.Output)throw new Exception("recipe collision "+r.Output+" / "+matched?.Output);if(CraftingTable.Take(inv,3,true)!=r.Count||inv.Count(r.Output)<r.Count)throw new Exception("transaction "+r.Output);checks++;}if(!Items.IsPick(150)||!Items.IsPick(151)||Items.ToolDrop(47)!=149)throw new Exception("diamond tools/drop");Console.Error.WriteLine("PASS "+checks+" actual managed recipes including every new weapon/diamond recipe; diamond pick tiers and drops.");var random=new Random(8265);for(int i=0;i<20000;i++){int seed=i%5==0?2506:random.Next(-1000000,1000000),x=random.Next(-1024,1025),z=random.Next(-1024,1025),y=random.Next(1,100);ushort id=TerrainGenerator.SampleContent(x,y,z,seed,Dimension.Lestingia,5);Console.WriteLine(seed+","+x+","+y+","+z+","+id);}}
}
